#!/usr/bin/env python3
"""
Unified Product Category Taxonomy Builder

This script processes category data from Amazon, Facebook, and Google Shopping
to create a unified 5-level taxonomy.
"""

import csv
import re
from collections import defaultdict, Counter
from typing import Dict, List, Tuple, Set
import os

# Configuration
INPUT_DIR = "/root/data"
OUTPUT_DIR = "/root/output"

# Target hierarchy constraints
MIN_TOP_CATEGORIES = 10
MAX_TOP_CATEGORIES = 20
MIN_SUBCATEGORIES = 3
MAX_SUBCATEGORIES = 20
MAX_LEVELS = 5
REPRESENTATIVENESS_THRESHOLD = 0.7
MAX_WORD_OVERLAP_SIBLINGS = 0.3
MAX_WORDS_PER_CATEGORY = 5


def clean_text(text: str) -> str:
    """Standardize category text."""
    if not text:
        return ""
    # Remove extra whitespace
    text = re.sub(r'\s+', ' ', text.strip())
    # Standardize case to Title Case
    text = text.title()
    # Remove special characters except alphanumeric, space, &, and -
    text = re.sub(r'[^\w\s&\-]', '', text)
    # Replace multiple spaces
    text = re.sub(r'\s+', ' ', text.strip())
    return text


def parse_category_path(path: str) -> List[str]:
    """Parse a category path string into a list of levels."""
    if not path:
        return []
    # Handle different separators
    parts = re.split(r'\s*>\s*', path)
    return [clean_text(p) for p in parts if p.strip()]


def load_amazon_categories(filepath: str) -> List[Tuple[str, List[str]]]:
    """Load Amazon category data."""
    categories = []
    with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        for row in reader:
            if row:
                path = row[0] if row else ""
                parsed = parse_category_path(path)
                if parsed:
                    categories.append(("amazon", parsed))
    return categories


def load_facebook_categories(filepath: str) -> List[Tuple[str, List[str]]]:
    """Load Facebook category data."""
    categories = []
    with open(filepath, 'r', encoding='utf-8-sig', errors='replace') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        for row in reader:
            if len(row) >= 2:
                path = row[1]
                parsed = parse_category_path(path)
                if parsed:
                    categories.append(("facebook", parsed))
    return categories


def load_google_categories(filepath: str) -> List[Tuple[str, List[str]]]:
    """Load Google Shopping category data."""
    categories = []
    with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        for row in reader:
            if row:
                path = row[0] if row else ""
                parsed = parse_category_path(path)
                if parsed:
                    categories.append(("google", parsed))
    return categories


def get_word_set(text: str) -> Set[str]:
    """Extract meaningful words from a category name."""
    # Remove common stop words and connectors
    stop_words = {'and', 'or', 'the', 'a', 'an', 'of', 'for', 'with', 'in', 'on', 'to', 'by'}
    words = re.findall(r'\b\w+\b', text.lower())
    return {w for w in words if w not in stop_words and len(w) > 1}


def word_overlap_ratio(text1: str, text2: str) -> float:
    """Calculate word overlap ratio between two texts."""
    words1 = get_word_set(text1)
    words2 = get_word_set(text2)
    if not words1 or not words2:
        return 0.0
    intersection = words1 & words2
    smaller_set = min(len(words1), len(words2))
    return len(intersection) / smaller_set if smaller_set > 0 else 0.0


def truncate_name(name: str, max_words: int = MAX_WORDS_PER_CATEGORY) -> str:
    """Truncate name to max words, keeping meaningful parts."""
    words = name.split()
    if len(words) <= max_words:
        return name
    return ' '.join(words[:max_words])


def create_unified_name(names: List[str], parent_name: str = "") -> str:
    """Create a unified representative name from a list of category names."""
    if not names:
        return ""

    # Count word frequencies
    word_freq = Counter()
    for name in names:
        words = get_word_set(name)
        for word in words:
            word_freq[word] += 1

    # Find most common meaningful words
    parent_words = get_word_set(parent_name) if parent_name else set()

    # Filter out parent words to avoid overlap
    filtered_words = [(w, c) for w, c in word_freq.most_common(10)
                      if w not in parent_words]

    if not filtered_words:
        filtered_words = word_freq.most_common(5)

    # Take top words that appear in at least 70% of names
    threshold_count = len(names) * 0.3  # Lower threshold for representative words
    representative_words = [w for w, c in filtered_words if c >= threshold_count][:MAX_WORDS_PER_CATEGORY]

    if not representative_words:
        # Fall back to most common words
        representative_words = [w for w, _ in filtered_words[:3]]

    if representative_words:
        return ' | '.join(w.title() for w in representative_words[:MAX_WORDS_PER_CATEGORY])

    # Fall back to most common name
    name_counter = Counter(names)
    return truncate_name(name_counter.most_common(1)[0][0])


class TaxonomyBuilder:
    """Builds a unified taxonomy from multiple sources."""

    def __init__(self):
        self.all_categories: List[Tuple[str, List[str]]] = []
        self.unified_taxonomy: Dict = {}  # Hierarchical structure
        self.category_mappings: List[Dict] = []  # Final mappings

    def load_all_sources(self):
        """Load categories from all sources."""
        amazon_file = os.path.join(INPUT_DIR, "amazon_product_categories.csv")
        facebook_file = os.path.join(INPUT_DIR, "fb_product_categories.csv")
        google_file = os.path.join(INPUT_DIR, "google_shopping_product_categories.csv")

        self.all_categories.extend(load_amazon_categories(amazon_file))
        self.all_categories.extend(load_facebook_categories(facebook_file))
        self.all_categories.extend(load_google_categories(google_file))

        print(f"Loaded {len(self.all_categories)} total categories")

        # Count by source
        source_counts = Counter(src for src, _ in self.all_categories)
        for src, count in source_counts.items():
            print(f"  {src}: {count}")

    def _build_category_tree(self) -> Dict:
        """Build a tree structure from all categories."""
        tree = {}
        for source, path in self.all_categories:
            node = tree
            for i, level in enumerate(path):
                if level not in node:
                    node[level] = {
                        '_sources': set(),
                        '_count': 0,
                        '_children': {},
                        '_original_names': [],
                        '_depth': i + 1
                    }
                node[level]['_sources'].add(source)
                node[level]['_count'] += 1
                node[level]['_original_names'].append(level)
                node = node[level]['_children']
        return tree

    def _extract_level1_candidates(self, tree: Dict) -> List[Tuple[str, Dict]]:
        """Extract top-level category candidates."""
        candidates = []
        for name, data in tree.items():
            if isinstance(data, dict) and '_count' in data:
                candidates.append((name, data))
        return sorted(candidates, key=lambda x: -x[1]['_count'])

    def _cluster_similar_categories(self, categories: List[Tuple[str, Dict]],
                                     threshold: float = 0.5) -> List[List[Tuple[str, Dict]]]:
        """Cluster similar categories based on name overlap."""
        if not categories:
            return []

        clusters = []
        used = set()

        for i, (name1, data1) in enumerate(categories):
            if i in used:
                continue

            cluster = [(name1, data1)]
            used.add(i)

            for j, (name2, data2) in enumerate(categories):
                if j in used:
                    continue
                if word_overlap_ratio(name1, name2) >= threshold:
                    cluster.append((name2, data2))
                    used.add(j)

            clusters.append(cluster)

        return clusters

    def _merge_cluster_to_name(self, cluster: List[Tuple[str, Dict]], parent: str = "") -> Tuple[str, Dict]:
        """Merge a cluster of similar categories into one unified name."""
        names = [name for name, _ in cluster]
        merged_data = {
            '_sources': set(),
            '_count': 0,
            '_children': {},
            '_original_names': [],
            '_depth': 1
        }

        for name, data in cluster:
            merged_data['_sources'].update(data.get('_sources', set()))
            merged_data['_count'] += data.get('_count', 0)
            merged_data['_original_names'].extend(data.get('_original_names', [name]))
            # Merge children
            for child_name, child_data in data.get('_children', {}).items():
                if child_name not in merged_data['_children']:
                    merged_data['_children'][child_name] = {
                        '_sources': set(),
                        '_count': 0,
                        '_children': {},
                        '_original_names': [],
                        '_depth': 2
                    }
                merged_data['_children'][child_name]['_sources'].update(child_data.get('_sources', set()))
                merged_data['_children'][child_name]['_count'] += child_data.get('_count', 0)
                merged_data['_children'][child_name]['_original_names'].extend(
                    child_data.get('_original_names', [child_name]))
                # Recursively merge grandchildren
                for gc_name, gc_data in child_data.get('_children', {}).items():
                    if gc_name not in merged_data['_children'][child_name]['_children']:
                        merged_data['_children'][child_name]['_children'][gc_name] = gc_data.copy()
                    else:
                        existing = merged_data['_children'][child_name]['_children'][gc_name]
                        existing['_count'] += gc_data.get('_count', 0)
                        existing['_sources'].update(gc_data.get('_sources', set()))

        unified_name = create_unified_name(names, parent)
        return unified_name, merged_data

    def build_unified_taxonomy(self):
        """Build the unified 5-level taxonomy."""
        print("\nBuilding unified taxonomy...")

        # Step 1: Build initial tree
        tree = self._build_category_tree()

        # Step 2: Extract and cluster top-level categories
        level1_candidates = self._extract_level1_candidates(tree)
        print(f"Found {len(level1_candidates)} unique top-level categories")

        # Create semantic mapping for level 1 categories
        semantic_groups = self._create_semantic_level1_groups(level1_candidates)

        # Build unified taxonomy
        self.unified_taxonomy = {}
        for group_name, members in semantic_groups.items():
            self.unified_taxonomy[group_name] = self._build_subtree(members, group_name, 2)

        print(f"Created {len(self.unified_taxonomy)} top-level categories")

        # Validate and balance
        self._validate_and_balance()

    def _create_semantic_level1_groups(self, candidates: List[Tuple[str, Dict]]) -> Dict[str, List[Tuple[str, Dict]]]:
        """Create semantic groupings for level 1 categories."""
        # Define semantic category mappings based on common e-commerce taxonomies
        semantic_mappings = {
            'Electronics | Technology': [
                'electronics', 'camera', 'photo', 'computer', 'laptop', 'phone', 'tablet',
                'audio', 'video', 'games', 'software', 'appliances', 'electrical'
            ],
            'Apparel | Fashion': [
                'clothing', 'shoes', 'jewelry', 'fashion', 'apparel', 'accessories',
                'watches', 'luggage', 'bags', 'handbags', 'costumes'
            ],
            'Home | Garden': [
                'home', 'kitchen', 'garden', 'patio', 'lawn', 'furniture', 'decor',
                'bedding', 'bath', 'dining', 'lighting', 'storage', 'organization'
            ],
            'Health | Beauty': [
                'health', 'beauty', 'personal care', 'cosmetics', 'skincare', 'haircare',
                'vitamins', 'supplements', 'wellness', 'medical', 'pharmacy'
            ],
            'Sports | Outdoors': [
                'sports', 'outdoor', 'fitness', 'exercise', 'recreation', 'camping',
                'hiking', 'cycling', 'hunting', 'fishing', 'athletic', 'sporting'
            ],
            'Food | Beverages': [
                'food', 'grocery', 'gourmet', 'beverages', 'drinks', 'snacks',
                'pantry', 'kitchen staples', 'organic', 'fresh'
            ],
            'Toys | Games': [
                'toys', 'games', 'hobbies', 'puzzles', 'dolls', 'action figures',
                'building', 'educational toys', 'collectibles'
            ],
            'Baby | Kids': [
                'baby', 'kids', 'children', 'infant', 'toddler', 'nursery',
                'maternity', 'pregnancy', 'child'
            ],
            'Pets | Animals': [
                'pet', 'pets', 'animal', 'dog', 'cat', 'fish', 'bird', 'reptile'
            ],
            'Automotive | Vehicles': [
                'automotive', 'car', 'vehicle', 'motorcycle', 'truck', 'auto parts',
                'powersports', 'rv', 'marine', 'boat'
            ],
            'Tools | Hardware': [
                'tools', 'hardware', 'home improvement', 'building', 'electrical',
                'plumbing', 'power tools', 'hand tools', 'welding'
            ],
            'Office | Business': [
                'office', 'business', 'school', 'supplies', 'stationery', 'printer',
                'desk', 'commercial', 'professional'
            ],
            'Arts | Crafts': [
                'arts', 'crafts', 'sewing', 'knitting', 'painting', 'drawing',
                'scrapbooking', 'beading', 'needlework', 'art supplies'
            ],
            'Books | Media': [
                'books', 'media', 'music', 'movies', 'cds', 'vinyl', 'dvd',
                'magazines', 'newspapers', 'publications', 'ebooks'
            ],
            'Industrial | Scientific': [
                'industrial', 'scientific', 'lab', 'laboratory', 'manufacturing',
                'commercial equipment', 'professional supplies', 'janitorial'
            ]
        }

        groups = defaultdict(list)
        assigned = set()

        for name, data in candidates:
            name_lower = name.lower()
            matched = False

            for group_name, keywords in semantic_mappings.items():
                for keyword in keywords:
                    if keyword in name_lower:
                        groups[group_name].append((name, data))
                        assigned.add(name)
                        matched = True
                        break
                if matched:
                    break

            if not matched:
                # Try partial matching
                for group_name, keywords in semantic_mappings.items():
                    name_words = get_word_set(name)
                    for keyword in keywords:
                        keyword_words = get_word_set(keyword)
                        if name_words & keyword_words:
                            groups[group_name].append((name, data))
                            assigned.add(name)
                            matched = True
                            break
                    if matched:
                        break

        # Handle unassigned categories
        for name, data in candidates:
            if name not in assigned:
                # Create miscellaneous group or add to closest match
                groups['Other | Miscellaneous'].append((name, data))

        # Remove empty groups and ensure we have 10-20 categories
        groups = {k: v for k, v in groups.items() if v}

        # Merge small groups if we have too many
        while len(groups) > MAX_TOP_CATEGORIES:
            # Find smallest group
            smallest = min(groups.keys(), key=lambda k: sum(d['_count'] for _, d in groups[k]))
            smallest_items = groups.pop(smallest)
            # Add to Other
            groups.setdefault('Other | Miscellaneous', []).extend(smallest_items)

        print(f"Created {len(groups)} semantic groups")
        for name, items in sorted(groups.items(), key=lambda x: -len(x[1])):
            source_counts = Counter()
            for _, data in items:
                for src in data.get('_sources', []):
                    source_counts[src] += 1
            print(f"  {name}: {len(items)} items ({dict(source_counts)})")

        return dict(groups)

    def _build_subtree(self, members: List[Tuple[str, Dict]], parent_name: str,
                       current_depth: int, max_depth: int = MAX_LEVELS) -> Dict:
        """Recursively build subtree for a group of categories."""
        if current_depth > max_depth or not members:
            return {}

        # Collect all children from members
        all_children = defaultdict(lambda: {
            '_sources': set(), '_count': 0, '_children': {}, '_original_names': [], '_depth': current_depth
        })

        for orig_name, data in members:
            for child_name, child_data in data.get('_children', {}).items():
                all_children[child_name]['_sources'].update(child_data.get('_sources', set()))
                all_children[child_name]['_count'] += child_data.get('_count', 0)
                all_children[child_name]['_original_names'].extend(
                    child_data.get('_original_names', [child_name]))
                # Merge grandchildren
                for gc_name, gc_data in child_data.get('_children', {}).items():
                    if gc_name not in all_children[child_name]['_children']:
                        all_children[child_name]['_children'][gc_name] = {
                            '_sources': gc_data.get('_sources', set()).copy(),
                            '_count': gc_data.get('_count', 0),
                            '_children': gc_data.get('_children', {}).copy(),
                            '_original_names': gc_data.get('_original_names', []).copy(),
                            '_depth': current_depth + 1
                        }
                    else:
                        existing = all_children[child_name]['_children'][gc_name]
                        existing['_sources'].update(gc_data.get('_sources', set()))
                        existing['_count'] += gc_data.get('_count', 0)
                        existing['_original_names'].extend(gc_data.get('_original_names', []))
                        # Deep merge children
                        for ggc_name, ggc_data in gc_data.get('_children', {}).items():
                            if ggc_name not in existing['_children']:
                                existing['_children'][ggc_name] = ggc_data.copy()

        if not all_children:
            return {}

        # Cluster similar children
        children_list = list(all_children.items())
        clusters = self._cluster_similar_categories(
            [(name, data) for name, data in children_list],
            threshold=0.4
        )

        # Limit to MAX_SUBCATEGORIES
        sorted_clusters = sorted(clusters, key=lambda c: -sum(d['_count'] for _, d in c))

        result = {}
        parent_words = get_word_set(parent_name)

        for i, cluster in enumerate(sorted_clusters[:MAX_SUBCATEGORIES]):
            if len(result) >= MAX_SUBCATEGORIES:
                break

            # Create unified name for cluster
            names = [name for name, _ in cluster]
            unified_name = create_unified_name(names, parent_name)

            # Ensure no overlap with parent
            unified_words = get_word_set(unified_name)
            if unified_words == parent_words or word_overlap_ratio(unified_name, parent_name) > 0.8:
                # Use most common original name instead
                name_counter = Counter(names)
                unified_name = truncate_name(name_counter.most_common(1)[0][0])

            # Ensure no overlap with siblings
            for existing_name in result.keys():
                if word_overlap_ratio(unified_name, existing_name) > MAX_WORD_OVERLAP_SIBLINGS:
                    # Differentiate by adding qualifier
                    if names:
                        unified_name = truncate_name(names[0])

            # Merge cluster data
            merged_data = {
                '_sources': set(),
                '_count': 0,
                '_children': {},
                '_original_names': [],
                '_depth': current_depth
            }
            for name, data in cluster:
                merged_data['_sources'].update(data.get('_sources', set()))
                merged_data['_count'] += data.get('_count', 0)
                merged_data['_original_names'].extend(data.get('_original_names', []))
                for gc_name, gc_data in data.get('_children', {}).items():
                    if gc_name not in merged_data['_children']:
                        merged_data['_children'][gc_name] = gc_data.copy()
                    else:
                        merged_data['_children'][gc_name]['_count'] += gc_data.get('_count', 0)
                        merged_data['_children'][gc_name]['_sources'].update(gc_data.get('_sources', set()))

            # Recursively build subtree
            subtree = self._build_subtree(
                [(unified_name, merged_data)],
                unified_name,
                current_depth + 1,
                max_depth
            )

            result[unified_name] = {
                '_sources': merged_data['_sources'],
                '_count': merged_data['_count'],
                '_original_names': merged_data['_original_names'],
                '_children': subtree,
                '_depth': current_depth
            }

        # Handle remaining clusters by merging into "Other"
        if len(sorted_clusters) > MAX_SUBCATEGORIES:
            other_items = []
            for cluster in sorted_clusters[MAX_SUBCATEGORIES:]:
                other_items.extend(cluster)
            if other_items:
                result['Other'] = {
                    '_sources': set().union(*(d.get('_sources', set()) for _, d in other_items)),
                    '_count': sum(d.get('_count', 0) for _, d in other_items),
                    '_original_names': [n for n, _ in other_items],
                    '_children': {},
                    '_depth': current_depth
                }

        return result

    def _validate_and_balance(self):
        """Validate and balance the taxonomy structure."""
        print("\nValidating taxonomy structure...")

        # Check level 1 count
        level1_count = len(self.unified_taxonomy)
        print(f"Level 1 categories: {level1_count}")

        if level1_count < MIN_TOP_CATEGORIES:
            print(f"  Warning: Less than {MIN_TOP_CATEGORIES} top categories")
        elif level1_count > MAX_TOP_CATEGORIES:
            print(f"  Warning: More than {MAX_TOP_CATEGORIES} top categories")

        # Check subcategory counts at each level
        def count_children(node, level=1, stats=None):
            if stats is None:
                stats = defaultdict(list)

            if isinstance(node, dict):
                children = {k: v for k, v in node.items() if not k.startswith('_')}
                if children:
                    stats[level].append(len(children))
                    for child_name, child_data in children.items():
                        if isinstance(child_data, dict) and '_children' in child_data:
                            count_children(child_data['_children'], level + 1, stats)
            return stats

        stats = count_children(self.unified_taxonomy)
        for level, counts in sorted(stats.items()):
            if counts:
                avg = sum(counts) / len(counts)
                print(f"  Level {level + 1}: avg {avg:.1f} subcategories "
                      f"(min={min(counts)}, max={max(counts)}, groups={len(counts)})")

    def map_categories_to_unified(self):
        """Map all original categories to the unified taxonomy."""
        print("\nMapping original categories to unified taxonomy...")

        self.category_mappings = []

        for source, original_path in self.all_categories:
            # Find best matching path in unified taxonomy
            unified_levels = self._find_best_match(original_path)

            # Pad to 5 levels
            while len(unified_levels) < MAX_LEVELS:
                unified_levels.append("")

            self.category_mappings.append({
                'source': source,
                'category_path': ' > '.join(original_path),
                'depth': len(original_path),
                'unified_level_1': unified_levels[0],
                'unified_level_2': unified_levels[1],
                'unified_level_3': unified_levels[2],
                'unified_level_4': unified_levels[3],
                'unified_level_5': unified_levels[4]
            })

        print(f"Mapped {len(self.category_mappings)} categories")

    def _find_best_match(self, original_path: List[str]) -> List[str]:
        """Find the best matching path in the unified taxonomy."""
        if not original_path:
            return ["Other | Miscellaneous"]

        # First, find the matching level 1 category
        first_level = original_path[0].lower()
        best_l1 = "Other | Miscellaneous"
        best_score = 0

        for l1_name in self.unified_taxonomy.keys():
            # Check word overlap
            score = word_overlap_ratio(first_level, l1_name.lower())
            if score > best_score:
                best_score = score
                best_l1 = l1_name

        # If no good match found, use keyword matching
        if best_score < 0.2:
            for l1_name in self.unified_taxonomy.keys():
                l1_words = get_word_set(l1_name)
                orig_words = get_word_set(first_level)
                if l1_words & orig_words:
                    best_l1 = l1_name
                    break

        unified_path = [best_l1]
        current_node = self.unified_taxonomy.get(best_l1, {}).get('_children', {})

        # Match remaining levels
        for i, level in enumerate(original_path[1:], start=1):
            if not current_node or i >= MAX_LEVELS:
                break

            level_lower = level.lower()
            best_match = None
            best_match_score = 0

            for unified_name, data in current_node.items():
                if unified_name.startswith('_'):
                    continue

                # Check if original level matches any original names in this node
                original_names = data.get('_original_names', [])
                for orig in original_names:
                    if orig.lower() == level_lower:
                        best_match = unified_name
                        best_match_score = 1.0
                        break

                if best_match_score >= 1.0:
                    break

                # Check word overlap
                score = word_overlap_ratio(level, unified_name)
                if score > best_match_score:
                    best_match_score = score
                    best_match = unified_name

            if best_match and best_match_score >= 0.2:
                unified_path.append(best_match)
                current_node = current_node.get(best_match, {}).get('_children', {})
            else:
                # No good match found, stop here
                break

        return unified_path

    def export_taxonomy_full(self):
        """Export the full taxonomy mapping to CSV."""
        filepath = os.path.join(OUTPUT_DIR, "unified_taxonomy_full.csv")

        with open(filepath, 'w', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=[
                'source', 'category_path', 'depth',
                'unified_level_1', 'unified_level_2', 'unified_level_3',
                'unified_level_4', 'unified_level_5'
            ])
            writer.writeheader()
            writer.writerows(self.category_mappings)

        print(f"\nExported full taxonomy to: {filepath}")
        print(f"  Total rows: {len(self.category_mappings)}")

    def export_taxonomy_hierarchy(self):
        """Export the unified hierarchy to CSV."""
        filepath = os.path.join(OUTPUT_DIR, "unified_taxonomy_hierarchy.csv")

        hierarchy_rows = []

        def traverse(node, path, level=1):
            for name, data in sorted(node.items()):
                if name.startswith('_'):
                    continue

                current_path = path + [name]
                # Pad path to 5 levels
                padded_path = current_path + [''] * (MAX_LEVELS - len(current_path))

                hierarchy_rows.append({
                    'unified_level_1': padded_path[0],
                    'unified_level_2': padded_path[1],
                    'unified_level_3': padded_path[2],
                    'unified_level_4': padded_path[3],
                    'unified_level_5': padded_path[4]
                })

                if isinstance(data, dict) and '_children' in data:
                    traverse(data['_children'], current_path, level + 1)

        traverse(self.unified_taxonomy, [])

        with open(filepath, 'w', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=[
                'unified_level_1', 'unified_level_2', 'unified_level_3',
                'unified_level_4', 'unified_level_5'
            ])
            writer.writeheader()
            writer.writerows(hierarchy_rows)

        print(f"\nExported hierarchy to: {filepath}")
        print(f"  Total rows: {len(hierarchy_rows)}")


def main():
    """Main entry point."""
    print("=" * 60)
    print("Unified Product Category Taxonomy Builder")
    print("=" * 60)

    builder = TaxonomyBuilder()

    # Load all sources
    builder.load_all_sources()

    # Build unified taxonomy
    builder.build_unified_taxonomy()

    # Map categories to unified taxonomy
    builder.map_categories_to_unified()

    # Export results
    builder.export_taxonomy_full()
    builder.export_taxonomy_hierarchy()

    print("\n" + "=" * 60)
    print("Done!")
    print("=" * 60)


if __name__ == "__main__":
    main()

